// ── Services (auto-slideshow on hover) ───────────────────────────────────────
function ServiceCard({ s, i }) {
  const [hov, setHov] = useState(false);
  const [slideIdx, setSlideIdx] = useState(0);
  const intervalRef = useRef(null);
  const touchStartX = useRef(null);
  const isPlayingRef = useRef(false);
  const videoRef = useRef(null);

  const isMobile = useRef(
    typeof window !== "undefined" && window.matchMedia("(hover: none) and (pointer: coarse)").matches
  ).current;

  const isVideo = s.video === true;

  const shuffledSlides = useRef(
    isVideo ? [] : [...s.slides].sort(() => Math.random() - 0.5)
  ).current;

  const MOBILE_INTERVAL = 2000;
  const DESKTOP_INTERVAL = 800;

  const startAutoPlay = (interval) => {
    if (shuffledSlides.length <= 1 || isPlayingRef.current) return;
    isPlayingRef.current = true;
    intervalRef.current = setInterval(() => {
      setSlideIdx(prev => (prev + 1) % shuffledSlides.length);
    }, interval);
  };

  const stopAutoPlay = (resetIdx = false) => {
    clearInterval(intervalRef.current);
    isPlayingRef.current = false;
    if (resetIdx) setSlideIdx(0);
  };

  const goTo = (idx) => {
    stopAutoPlay(false);
    setSlideIdx(((idx % shuffledSlides.length) + shuffledSlides.length) % shuffledSlides.length);
  };

  // Video controls
  const playVideo = () => {
    if (videoRef.current) {
      videoRef.current.currentTime = 0;
      videoRef.current.play().catch(() => {});
    }
  };
  const pauseVideo = () => {
    if (videoRef.current) {
      videoRef.current.pause();
      videoRef.current.currentTime = 0;
    }
  };

  useEffect(() => {
    if (!isVideo && isMobile) startAutoPlay(MOBILE_INTERVAL);
    if (isVideo) playVideo();
    return () => { stopAutoPlay(); };
  }, []);

  const handleHoverStart = () => {
    if (isMobile) return;
    setHov(true);
    if (isVideo) playVideo();
    else startAutoPlay(DESKTOP_INTERVAL);
  };
  const handleHoverEnd = () => {
    if (isMobile) return;
    setHov(false);
    if (!isVideo) stopAutoPlay(true);
  };

  const handleTap = () => {
    if (!isMobile || isVideo) return;
    if (isPlayingRef.current) { stopAutoPlay(false); }
    else { setSlideIdx(prev => (prev + 1) % shuffledSlides.length); startAutoPlay(MOBILE_INTERVAL); }
  };

  const handleTouchStart = (e) => { if (isMobile && !isVideo) touchStartX.current = e.touches[0].clientX; };
  const handleTouchEnd = (e) => {
    if (!isMobile || isVideo || touchStartX.current === null) return;
    const dx = e.changedTouches[0].clientX - touchStartX.current;
    if (Math.abs(dx) > 40) goTo(slideIdx + (dx < 0 ? 1 : -1));
    touchStartX.current = null;
  };

  const isActive = hov || isMobile;

  return (
    <FadeUp delay={i * 0.1}>
      <motion.div
        className="relative overflow-hidden"
        style={{ background: C.darkMid, height: "100%", display: "flex", flexDirection: "column" }}
        onHoverStart={handleHoverStart}
        onHoverEnd={handleHoverEnd}
        onTap={handleTap}
        onTouchStart={handleTouchStart}
        onTouchEnd={handleTouchEnd}
        whileHover={!isMobile ? { background: "#1c1c1c" } : {}}
      >
        <div className="relative overflow-hidden" style={{ height: 210 }}>

          {isVideo ? (
            <>
              <video
                ref={videoRef}
                muted
                loop
                playsInline
                preload="metadata"
                className="absolute inset-0 w-full h-full object-cover"
                style={{
                  transition: "filter 0.5s ease, transform 0.6s ease",
                  filter: isActive ? "brightness(0.92) saturate(1.1)" : "brightness(0.6) saturate(0.7)",
                  transform: isActive ? "scale(1.06)" : "scale(1)",
                  willChange: "transform",
                }}
              >
                <source src={MOTION_VIDEO} type="video/mp4" />
              </video>

            </>
          ) : (
            <>
              {shuffledSlides.map((key, idx) => (
                <img
                  key={key}
                  src={IMG[key]}
                  alt={s.title}
                  loading="lazy"
                  className="absolute inset-0 w-full h-full object-cover"
                  style={{
                    opacity: idx === slideIdx ? 1 : 0,
                    transition: "opacity 0.5s ease, filter 0.5s ease, transform 0.6s ease",
                    filter: isActive ? "brightness(0.92) saturate(1.1)" : "brightness(0.6) saturate(0.7)",
                    transform: isActive ? "scale(1.06)" : "scale(1)",
                    willChange: "opacity, transform",
                  }}
                />
              ))}
              {shuffledSlides.length > 1 && (
                <div className="absolute bottom-3 left-0 right-0 flex justify-center gap-1.5 z-10 px-4">
                  {shuffledSlides.map((_, idx) => (
                    <button key={idx} onClick={(e) => { e.stopPropagation(); goTo(idx); }}
                      className="rounded-full transition-all duration-300 flex-shrink-0"
                      style={{ width: idx === slideIdx ? 18 : 6, height: 6,
                        background: idx === slideIdx ? C.red : "rgba(255,255,255,0.35)",
                        border: "none", cursor: "pointer", padding: 0 }} />
                  ))}
                </div>
              )}
              {!isMobile && hov && shuffledSlides.length > 1 && (
                <>
                  <button onClick={(e) => { e.stopPropagation(); goTo(slideIdx - 1); }}
                    className="absolute left-2 top-1/2 -translate-y-1/2 z-20 flex items-center justify-center"
                    style={{ width: 28, height: 28, background: "rgba(0,0,0,0.5)", border: `1px solid ${C.red}`, color: C.white, cursor: "pointer", fontSize: "0.75rem" }}>‹</button>
                  <button onClick={(e) => { e.stopPropagation(); goTo(slideIdx + 1); }}
                    className="absolute right-2 top-1/2 -translate-y-1/2 z-20 flex items-center justify-center"
                    style={{ width: 28, height: 28, background: "rgba(0,0,0,0.5)", border: `1px solid ${C.red}`, color: C.white, cursor: "pointer", fontSize: "0.75rem" }}>›</button>
                </>
              )}
            </>
          )}

          {/* Shared overlays */}
          <div className="absolute inset-0"
            style={{ background: "linear-gradient(to top, rgba(22,22,22,1) 0%, transparent 55%)" }} />
          <motion.div
            className="absolute inset-0"
            style={{ background: "linear-gradient(to top, rgba(212,43,10,0.2) 0%, transparent 50%)" }}
            animate={{ opacity: hov ? 1 : 0 }}
            transition={{ duration: 0.3 }}
          />
          <motion.div className="absolute left-0 top-0 bottom-0 w-1"
            style={{ background: C.red, transformOrigin: "bottom" }}
            animate={{ scaleY: hov ? 1 : 0 }}
            transition={{ duration: 0.35 }} />
        </div>

        <div className="p-7" style={{ flex: 1 }}>
          <span className="text-xs font-bold uppercase tracking-widest block mb-2"
            style={{ color: C.red, fontFamily: "'Rajdhani',sans-serif", letterSpacing: "0.25em" }}>{s.tag}</span>
          <h3 className="font-black uppercase text-xl mb-3"
            style={{ fontFamily: "'Rajdhani',sans-serif", color: C.white }}>{s.title}</h3>
          <p className="text-sm leading-relaxed" style={{ color: C.muted }}>{s.desc}</p>
        </div>
      </motion.div>
    </FadeUp>
  );
}
