// ── Full-bleed split ──────────────────────────────────────────────────────────
function FullBleedSplit() {
  const T = "w_1600,c_scale,q_auto:best,f_auto";
  const B = `https://res.cloudinary.com/dwsm6vx7d/image/upload/${T}`;

  const imgPool = [
    // Orkan — cinematic
    `${B}/v1782075908/01-Cine_ynfel7.png`,
    `${B}/v1782076309/04-Cine_v5mcxc.png`,
    `${B}/v1782075920/08-Cine_agkrai.png`,
    // Orkan — hero
    `${B}/v1782076998/Orkan-Beauty_1_w6rqt6.png`,
    `${B}/v1782077175/Orkan-Beauty_8_j85u6m.png`,
    // Orkan — design
    `${B}/v1782163913/ORKAN-1_o77q2i.png`,
    // 77R — design sketch
    `${B}/v1782151194/77R-Design_0_vb2nn3.png`,
    `${B}/v1782151196/77R-Design_2_e1rkqr.png`,
    // 77R — hero
    `${B}/v1782143291/77R-Hero_1_wauenk.png`,
    `${B}/v1782143345/77R-Hero_11_ujucgb.png`,
    `${B}/v1782143340/77R-Hero_24_kc2nko.png`,
    // Honda Monkey — sketch et render
    IMG.hm_1, IMG.hm_9, IMG.hm_15, IMG.hm_17,
    // Gin 44
    `${B}/v1782080051/Gin44_1_yjbfta.png`,
    `${B}/v1782080056/Gin44_5_fyrtmi.png`,
    `${B}/v1782080064/Gin44_11_kqgwnw.png`,
    // Divers
    IMG.strip_northface2, IMG.strip_mr2, IMG.strip_van,
    IMG.strip_bolt, IMG.strip_hinomaru, IMG.strip_bottle,
    IMG.strip_brp, IMG.strip_scooter_red, IMG.strip_bug_pink,
    IMG.volvo_portrait, IMG.sk77_wide,
  ].filter(Boolean);

  const pick2 = (pool) => {
    const s = [...pool].sort(() => Math.random() - 0.5);
    return [s[0], s[1]];
  };

  const [pair, setPair] = useState(() => pick2(imgPool));
  const ref = useRef(null);

  useEffect(() => {
    const observer = new IntersectionObserver(
      ([entry]) => { if (entry.isIntersecting) setPair(pick2(imgPool)); },
      { threshold: 0.3 }
    );
    if (ref.current) observer.observe(ref.current);
    return () => observer.disconnect();
  }, []);

  return (
    <section ref={ref} className="relative overflow-hidden" style={{ background: C.dark }}>
      <div className="max-w-screen-2xl mx-auto relative">
        <div className="grid grid-cols-2" style={{ height: 280 }}>
          <div className="relative overflow-hidden">
            <img key={pair[0]} src={pair[0]} alt="" className="w-full h-full object-cover"
              style={{ filter: "brightness(0.85) saturate(0.85)" }} />
          </div>
          <div className="relative overflow-hidden">
            <img key={pair[1]} src={pair[1]} alt="" className="w-full h-full object-cover"
              style={{ filter: "brightness(0.85) saturate(0.85)" }} />
          </div>
        </div>
        {/* Séparateur rouge vertical */}
        <div className="absolute left-1/2 top-0 bottom-0 w-px -translate-x-px"
          style={{ background: "rgba(212,43,10,0.6)" }} />
        {/* Badge WORKS */}
        <div className="absolute left-1/2 top-1/2 -translate-x-1/2 -translate-y-1/2 z-10">
          <div className="px-5 py-2 font-black uppercase text-xs tracking-widest text-white"
            style={{ background: C.red, fontFamily: "'Rajdhani',sans-serif", letterSpacing: "0.25em" }}>Works</div>
        </div>
      </div>
    </section>
  );
}

// ── Projects grid + lightbox ──────────────────────────────────────────────────
