// ── App ───────────────────────────────────────────────────────────────────────
export default function App() {
  const [active, setActive] = useState("home");

  const go = (section) => {
    setActive(section);
    if (section === "home") { window.scrollTo({ top: 0, behavior: "smooth" }); return; }
    const el = document.getElementById(section);
    if (el) el.scrollIntoView({ behavior: "smooth" });
  };

  useEffect(() => {
    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = "https://fonts.googleapis.com/css2?family=Rajdhani:wght@500;600;700&family=Inter:wght@300;400;500&display=swap";
    document.head.appendChild(link);
    return () => document.head.removeChild(link);
  }, []);

  return (
    <div style={{ background: C.dark, minHeight: "100vh" }}>
      <Nav active={active} go={go} />
      <Hero go={go} />
      <BannerStrip />
      <Services />
      <FullBleedSplit />
      <Projects />
      <About />
      <Contact />
      <Footer go={go} />
    </div>
  );
}
